-- ============================================================
-- Kairo Phase 5.8: Usage Metering Schema — PostgreSQL
-- ============================================================
-- Additive-only: no existing tables are altered.
-- Safe to run on an existing kairo_dev database.
-- Run as: psql -h <host> -d kairo_dev -f phase5_usage_schema_postgresql.sql
-- ============================================================

-- ── UsageLedger ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "UsageLedger" (
    "EntryId"       BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    "UserId"        BIGINT        NOT NULL,
    "ProjectId"     BIGINT        NOT NULL,
    "OperationType" VARCHAR(50)   NOT NULL,
    "Outcome"       VARCHAR(20)   NOT NULL DEFAULT 'Success',
    "OccurredAt"    TIMESTAMP(3)  NOT NULL,
    "UnitCount"     INT           NOT NULL DEFAULT 1,
    "TokensUsed"    INT           NULL,

    CONSTRAINT "PK_UsageLedger" PRIMARY KEY ("EntryId"),

    CONSTRAINT "FK_UsageLedger_Users"
        FOREIGN KEY ("UserId") REFERENCES "Users" ("UserId"),

    CONSTRAINT "FK_UsageLedger_Projects"
        FOREIGN KEY ("ProjectId") REFERENCES "Projects" ("ProjectId")
);

-- Time-windowed per-project aggregation.
CREATE INDEX IF NOT EXISTS "IX_UsageLedger_Project_OccurredAt"
    ON "UsageLedger" ("ProjectId", "OccurredAt");

CREATE INDEX IF NOT EXISTS "IX_UsageLedger_User_OccurredAt"
    ON "UsageLedger" ("UserId", "OccurredAt");

-- Quota enforcement (includes OperationType).
CREATE INDEX IF NOT EXISTS "IX_UsageLedger_Project_Op_OccurredAt"
    ON "UsageLedger" ("ProjectId", "OperationType", "OccurredAt");


-- ── ProjectQuotas ────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "ProjectQuotas" (
    "ProjectId"              BIGINT        NOT NULL,
    "MaxOperationsPerMinute" INT           NULL,
    "MaxOperationsPerDay"    INT           NULL,
    "MaxTotalMemories"       INT           NULL,
    "MaxBatchSize"           INT           NULL,
    "UpdatedAt"              TIMESTAMP(3)  NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),

    CONSTRAINT "PK_ProjectQuotas" PRIMARY KEY ("ProjectId"),

    CONSTRAINT "FK_ProjectQuotas_Projects"
        FOREIGN KEY ("ProjectId") REFERENCES "Projects" ("ProjectId")
);
